using System;
using System.Linq;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;
namespace JingFamily {
 public static class StudioStyle {
  public static readonly Color Green=Color.FromArgb(28,78,61),Canvas=Color.FromArgb(244,247,243),Ink=Color.FromArgb(36,56,47),Muted=Color.FromArgb(113,130,119),Border=Color.FromArgb(222,231,223),Gold=Color.FromArgb(177,139,77),Nav=Color.FromArgb(23,57,47),NavActive=Color.FromArgb(48,91,72),NavText=Color.FromArgb(213,229,218),Red=Color.FromArgb(169,66,58);
  public static Font Font(float size=10,FontStyle style=FontStyle.Regular){return new Font("Microsoft YaHei UI",size,style);}
  public static GraphicsPath Round(RectangleF r,float radius){float d=Math.Max(1,Math.Min(radius*2,Math.Min(r.Width,r.Height)));var p=new GraphicsPath();p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
  public static Color Mix(Color a,Color b,float amount){return Color.FromArgb((int)(a.R+(b.R-a.R)*amount),(int)(a.G+(b.G-a.G)*amount),(int)(a.B+(b.B-a.B)*amount));}
  public static void StyleCombo(ComboBox combo){combo.FlatStyle=FlatStyle.Flat;combo.Font=Font(10);combo.ForeColor=Ink;combo.BackColor=Color.White;if(combo.DrawMode!=DrawMode.OwnerDrawFixed){combo.DrawMode=DrawMode.OwnerDrawFixed;combo.ItemHeight=25;combo.DrawItem+=(s,e)=>{if(e.Bounds.Width<=0)return;bool selected=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(selected?Color.FromArgb(228,241,231):Color.White))e.Graphics.FillRectangle(b,e.Bounds);string text=e.Index>=0&&e.Index<combo.Items.Count?combo.GetItemText(combo.Items[e.Index]):combo.Text;var rect=new Rectangle(e.Bounds.X+8,e.Bounds.Y,e.Bounds.Width-12,e.Bounds.Height);TextRenderer.DrawText(e.Graphics,text,combo.Font,rect,Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis);};}}
  public static void Polish(Control root){foreach(Control c in root.Controls){var text=c as TextBox;if(text!=null){text.Font=Font(10);text.ForeColor=Ink;text.BackColor=text.ReadOnly?Canvas:Color.White;if(!(text.Parent is InputFrame)&&text.BorderStyle!=BorderStyle.None)text.BorderStyle=BorderStyle.FixedSingle;}var combo=c as ComboBox;if(combo!=null){StyleCombo(combo);}var list=c as CheckedListBox;if(list!=null){list.Font=Font(10);list.BorderStyle=BorderStyle.FixedSingle;list.BackColor=Color.White;list.ForeColor=Ink;}var check=c as CheckBox;if(check!=null){check.Font=Font(9.5f);check.ForeColor=Ink;}var radio=c as RadioButton;if(radio!=null){radio.Font=Font(9.5f);radio.ForeColor=Ink;}Polish(c);}}
 }
 public class StudioButton:Button {
  bool hover,down;public bool Navigation=false;
  public StudioButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw|ControlStyles.SupportsTransparentBackColor,true);FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;BackColor=Color.White;ForeColor=StudioStyle.Green;Font=StudioStyle.Font();Cursor=Cursors.Hand;}
  protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hover=false;down=false;Invalidate();base.OnMouseLeave(e);}protected override void OnMouseDown(MouseEventArgs e){down=true;Invalidate();base.OnMouseDown(e);}protected override void OnMouseUp(MouseEventArgs e){down=false;Invalidate();base.OnMouseUp(e);}protected override void OnGotFocus(EventArgs e){Invalidate();base.OnGotFocus(e);}protected override void OnLostFocus(EventArgs e){Invalidate();base.OnLostFocus(e);}
  Color Surface(){Control parent=Parent;while(parent!=null){var surface=parent as RoundedSurface;if(surface!=null)return surface.SurfaceColor;if(parent.BackColor.A==255)return parent.BackColor;parent=parent.Parent;}return StudioStyle.Canvas;}
  protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Surface());Color fill=BackColor;bool dark=fill.GetBrightness()<.5f;if(!Enabled)fill=StudioStyle.Mix(fill,StudioStyle.Canvas,.65f);else if(down)fill=StudioStyle.Mix(fill,dark?Color.Black:StudioStyle.Green,.12f);else if(hover)fill=StudioStyle.Mix(fill,dark?Color.White:StudioStyle.Green,.075f);var r=new RectangleF(.8f,.8f,Width-2,Height-2);using(var path=StudioStyle.Round(r,Navigation?11:9)){using(var b=new SolidBrush(fill))g.FillPath(b,path);using(var p=new Pen(dark?fill:StudioStyle.Border,1))g.DrawPath(p,path);}if(Navigation&&BackColor==StudioStyle.NavActive){using(var path=StudioStyle.Round(new RectangleF(7,12,3,Height-24),1.5f))using(var b=new SolidBrush(StudioStyle.Gold))g.FillPath(b,path);}Rectangle text=new Rectangle(Navigation?18:9,1,Width-(Navigation?26:18),Height-2);var flags=TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix;flags|=Navigation||TextAlign==ContentAlignment.MiddleLeft?TextFormatFlags.Left:TextFormatFlags.HorizontalCenter;TextRenderer.DrawText(g,Text,Font,text,Enabled?ForeColor:StudioStyle.Muted,flags);if(Focused&&ShowFocusCues){using(var p=new Pen(StudioStyle.Gold,1.4f)){p.DashStyle=DashStyle.Dot;using(var path=StudioStyle.Round(new RectangleF(4,4,Width-9,Height-9),7))g.DrawPath(p,path);}}}
 }
 public class RoundedSurface:Panel {
  public Color SurfaceColor=Color.White;public float Radius=16;
  public RoundedSurface(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw|ControlStyles.SupportsTransparentBackColor,true);BackColor=Color.Transparent;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Width<3||Height<6)return;var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;using(var shadow=StudioStyle.Round(new RectangleF(1,3,Width-2,Height-4),Radius))using(var b=new SolidBrush(Color.FromArgb(232,237,231)))g.FillPath(b,shadow);using(var path=StudioStyle.Round(new RectangleF(.5f,.5f,Width-1,Height-4),Radius)){using(var b=new SolidBrush(SurfaceColor))g.FillPath(b,path);using(var p=new Pen(StudioStyle.Border,1))g.DrawPath(p,path);}}
 }
 public class InputFrame:Panel {
  Control input;bool multi;
  public InputFrame(Control child){input=child;multi=child is TextBox&&((TextBox)child).Multiline;DoubleBuffered=true;SetStyle(ControlStyles.SupportsTransparentBackColor,true);BackColor=Color.Transparent;Padding=new Padding(12,7,12,7);child.Dock=DockStyle.None;child.Margin=Padding.Empty;child.Font=StudioStyle.Font(10.5f);child.ForeColor=StudioStyle.Ink;child.BackColor=Color.White;var t=child as TextBox;if(t!=null)t.BorderStyle=BorderStyle.None;var c=child as ComboBox;if(c!=null)StudioStyle.StyleCombo(c);Controls.Add(child);child.GotFocus+=(s,e)=>Invalidate();child.LostFocus+=(s,e)=>Invalidate();SizeChanged+=(s,e)=>Arrange();Click+=(s,e)=>child.Focus();Arrange();}
  void Arrange(){if(input==null)return;int h=multi?Math.Max(20,ClientSize.Height-18):input.PreferredSize.Height;input.SetBounds(12,multi?9:Math.Max(4,(ClientSize.Height-h)/2),Math.Max(20,ClientSize.Width-24),h);}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Width<3||Height<3)return;e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var path=StudioStyle.Round(new RectangleF(1,1,Width-3,Height-3),8)){using(var fill=new SolidBrush(Color.White))e.Graphics.FillPath(fill,path);using(var p=new Pen(ContainsFocus?StudioStyle.Green:StudioStyle.Border,ContainsFocus?1.6f:1))e.Graphics.DrawPath(p,path);}}
 }
 public class PillTabs:TabControl {
  public PillTabs(){DrawMode=TabDrawMode.OwnerDrawFixed;SizeMode=TabSizeMode.Fixed;ItemSize=new Size(158,43);Padding=new Point(14,9);Font=StudioStyle.Font(10);SetStyle(ControlStyles.OptimizedDoubleBuffer,true);}
  protected override void OnDrawItem(DrawItemEventArgs e){bool active=e.Index==SelectedIndex;var r=GetTabRect(e.Index);r.Inflate(-3,-4);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var p=StudioStyle.Round(r,9))using(var b=new SolidBrush(active?StudioStyle.Green:StudioStyle.Canvas))e.Graphics.FillPath(b,p);using(var font=StudioStyle.Font(10,active?FontStyle.Bold:FontStyle.Regular))TextRenderer.DrawText(e.Graphics,TabPages[e.Index].Text,font,r,active?Color.White:StudioStyle.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis);}
 }
 public class StudioGrid:DataGridView {
  public string EmptyTitle="暂无记录",EmptyNote="添加内容后，它们会显示在这里。";
  public StudioGrid(){DoubleBuffered=true;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Rows.Count!=0||ClientSize.Height<180)return;int x=ClientSize.Width/2,y=ColumnHeadersHeight+(ClientSize.Height-ColumnHeadersHeight)/2-32;e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var b=new SolidBrush(Color.FromArgb(237,244,237)))e.Graphics.FillEllipse(b,x-27,y-28,54,54);using(var p=new Pen(StudioStyle.Green,2)){e.Graphics.DrawRectangle(p,x-11,y-9,22,19);e.Graphics.DrawLine(p,x-7,y-3,x+7,y-3);e.Graphics.DrawLine(p,x-7,y+3,x+3,y+3);}using(var f=StudioStyle.Font(12,FontStyle.Bold))TextRenderer.DrawText(e.Graphics,EmptyTitle,f,new Rectangle(10,y+42,ClientSize.Width-20,30),StudioStyle.Ink,TextFormatFlags.HorizontalCenter);using(var f=StudioStyle.Font(9))TextRenderer.DrawText(e.Graphics,EmptyNote,f,new Rectangle(10,y+76,ClientSize.Width-20,32),StudioStyle.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.EndEllipsis);}
 }
 public class StatSurface:RoundedSurface {
  string value,label,glyph;
  public StatSurface(string number,string caption,string symbol){value=number;label=caption;glyph=symbol;Height=142;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);int x=Math.Max(120,Width-62);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var b=new SolidBrush(Color.FromArgb(238,244,237)))e.Graphics.FillEllipse(b,x,19,36,36);using(var f=StudioStyle.Font(12,FontStyle.Bold))TextRenderer.DrawText(e.Graphics,glyph,f,new Rectangle(x,19,36,36),StudioStyle.Green,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);using(var f=StudioStyle.Font(29,FontStyle.Bold))TextRenderer.DrawText(e.Graphics,value,f,new Rectangle(20,27,Width-42,51),StudioStyle.Green,TextFormatFlags.Left|TextFormatFlags.NoPadding|TextFormatFlags.EndEllipsis);using(var f=StudioStyle.Font(10))TextRenderer.DrawText(e.Graphics,label,f,new Rectangle(23,96,Width-40,28),StudioStyle.Muted,TextFormatFlags.Left|TextFormatFlags.NoPadding);}
 }
}
